static boolean detectDirtyRead(String url) throws SQLException {
  try (Connection connA = DriverManager.getConnection(url); Connection connB = DriverManager.getConnection(url)) {
    connA.setAutoCommit(false); connB.setAutoCommit(false);
    connB.setTransactionIsolation(Connection.TRANSACTION_READ_UNCOMMITTED);
    connA.createStatement().executeUpdate("UPDATE accounts SET balance=1 WHERE id=1");
    ResultSet rs = connB.createStatement().executeQuery("SELECT balance FROM accounts WHERE id=1"); rs.next();
    boolean dirty = rs.getInt("balance") == 1;
    connA.rollback(); connB.commit();
    return dirty;
  }
}

