static boolean updatePriceOptimistic(Connection conn, int id, BigDecimal price, int expectedVersion) throws SQLException {
  try (PreparedStatement ps = conn.prepareStatement("UPDATE products SET price=?, version=version+1 WHERE id=? AND version=?")) {
    ps.setBigDecimal(1, price); ps.setInt(2, id); ps.setInt(3, expectedVersion);
    return ps.executeUpdate() > 0;
  }
}

