static String classifyAnomaly(String url, int level) throws SQLException {
  try (Connection connA = DriverManager.getConnection(url); Connection connB = DriverManager.getConnection(url)) {
    connA.setTransactionIsolation(level); connA.setAutoCommit(false); connB.setAutoCommit(false);
    int r1 = readBalance(connA);
    connB.createStatement().executeUpdate("UPDATE accounts SET balance=balance+1 WHERE id=1"); connB.commit();
    int r2 = readBalance(connA); connA.commit();
    return r1 != r2 ? "NON_REPEATABLE_READ_WYSTAPIL" : "BRAK_ANOMALII";
  }
}

