static boolean safeWithdraw(Connection conn, int id, int amount) throws SQLException {
  for (int attempt = 0; attempt < 3; attempt++) {
    int[] state = readBalanceAndVersion(conn, id); // {balance, version}
    if (state[0] < amount) return false;
    int newBalance = state[0] - amount;
    try (PreparedStatement ps = conn.prepareStatement("UPDATE accounts SET balance=?, version=version+1 WHERE id=? AND version=?")) {
      ps.setInt(1,newBalance); ps.setInt(2,id); ps.setInt(3,state[1]);
      if (ps.executeUpdate() > 0) return true;
    }
  }
  return false; // 3 proby nieudane
}
